(function(){'use strict';const S=window.KERN_SHAPES,O=window.KERN_OBJECTS;let gesture=null,pivot=null;const button=document.createElement('button');button.id='tool-rotate';button.innerHTML='Rotate <kbd>E</kbd>';button.title='E · Click a corner for the pivot, drag another corner to rotate · Shift: world 5°';button.setAttribute('aria-keyshortcuts','E');$('tool-select').after(button);
const norm=a=>(a%360+360)%360;
function angle(o,key='rooms'){if(key==='rooms'){const p=S.raw(o);return norm(Math.atan2(p[1][1]-p[0][1],p[1][0]-p[0][0])*180/Math.PI);}if(o.points){const [a,b]=o.points;return norm(Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI);}return norm(o.rotation||0);}
function delta(o,d,shift,key='rooms'){return shift?Math.round((angle(o,key)+d)/5)*5-angle(o,key):d;}
function bounds(o){if(o.points){const xs=o.points.map(p=>p.x),ys=o.points.map(p=>p.y);return{x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)}}if(o.text!==undefined){const size=o.fontSize||.45;return{x:o.x-Math.max(1,o.text.length)*size*.29,y:o.y-size,w:Math.max(1,o.text.length)*size*.58,h:size*1.3}}return o;}
function center(o){const b=bounds(o);return{x:b.x+b.w/2,y:b.y+b.h/2};}
function turn(p,c,d){const a=d*Math.PI/180,x=p[0]-c.x,y=p[1]-c.y;return[c.x+x*Math.cos(a)-y*Math.sin(a),c.y+x*Math.sin(a)+y*Math.cos(a)];}
function points(o,key){if(key==='rooms')return S.raw(o);if(o.points)return o.points.map(p=>[p.x,p.y]);const b=bounds(o),c=center(o),ps=[[b.x,b.y],[b.x+b.w,b.y],[b.x+b.w,b.y+b.h],[b.x,b.y+b.h]];return ps.map(p=>turn(p,c,key==='symbols'&&!o.rotationSpace?0:o.rotation||0));}
function eligible(o,key){return o&&(key!=='rooms'||canEdit(o)&&(o.routeStair||!isStair(o)&&!o.stairTransition));}
function target(){const s=getSelection();for(const key of ['rooms','symbols','services','annotations'])if(s[key]?.length===1){const o=key==='rooms'?room(s[key][0]):extraObject(key,s[key][0]);if(eligible(o,key))return{key,o};}return null;}
function prepare(o,key){if(key==='rooms'){if(!o.shape)o.shape={vertices:S.vertices(o).map(v=>({...v,r:0}))};for(const d of allConnections())if(d.a===o.id&&!d.edge){const w=S.wall(d,floor());if(w)d.edge=w.edge;}}else if(key==='symbols'&&!o.rotationSpace){if((o.rotation||0)%180){const c=center(o),w=o.w;o.w=o.h;o.h=w;o.x=c.x-o.w/2;o.y=c.y-o.h/2;}o.rotationSpace='intrinsic';}}
function apply(o,original,d,key,origin=center(original)){Object.assign(o,clone(original));if(key==='rooms'){if(!S.rotate(o,d,origin))return false;syncStairEdit(o);}else if(o.points){const c=origin;o.points=original.points.map(p=>{const q=turn([p.x,p.y],c,d);return{x:cleanNumber(q[0]),y:cleanNumber(q[1])};});}else{const c=center(original),q=turn([c.x,c.y],origin,d);o.x=cleanNumber(original.x+q[0]-c.x);o.y=cleanNumber(original.y+q[1]-c.y);o.rotation=cleanNumber(norm((original.rotation||0)+d));}return true;}
function pivotFor(o,key='rooms'){if(!pivot||pivot.scope!==currentBuilding().id+':'+floorId||pivot.id!==o.id||pivot.key!==key)return null;const p=points(o,key)[pivot.index];return p?{x:p[0],y:p[1],index:pivot.index}:null;}
function choosePivot(o,key,index){pivot={scope:currentBuilding().id+':'+floorId,key,id:o.id,index};}
function cancel(){window.BuildingExports?.getViewer()?.cancelEdit?.();if(gesture){model=JSON.parse(gesture.before);gesture=null;render();}}
function sync(){button.setAttribute('aria-pressed',String(tool==='rotate'));}
button.onclick=()=>{cancel();window.KERN_SHAPE_UI?.cancel();setTool(tool==='rotate'?'select':'rotate');sync();window.BuildingExports?.getViewer()?.selectRoom?.(floorId,selected);};
function feedback(c,start,degrees,cursor){if(!c||!cursor||!Number.isFinite(degrees))return '';const length=Math.hypot(cursor.x-c.x,cursor.y-c.y),radius=Math.min(length,screenUnits(90))*.8,end=start+degrees*Math.PI/180,ps=[];for(let i=0,n=Math.max(2,Math.min(160,Math.ceil(Math.abs(degrees)/5)));i<=n;i++){const a=start+(end-start)*i/n;ps.push([c.x+Math.cos(a)*radius,c.y+Math.sin(a)*radius]);}const a={x:c.x+Math.cos(start)*length,y:c.y+Math.sin(start)*length},b={x:c.x+Math.cos(end)*length,y:c.y+Math.sin(end)*length},label=(degrees>0?'+':'')+degrees.toFixed(1)+'°',x=cursor.x+screenUnits(16),y=cursor.y-screenUnits(18);return `<g data-rotation-feedback pointer-events="none"><path d="M${a.x} ${a.y}L${c.x} ${c.y}L${b.x} ${b.y}M${ps.map(p=>p.join(' ')).join('L')}" fill="none" stroke="#e7b76e" stroke-width="${screenUnits(1.5)}" stroke-dasharray="${screenUnits(5)} ${screenUnits(4)}"/><rect x="${x-screenUnits(7)}" y="${y-screenUnits(16)}" width="${screenUnits(label.length*8+14)}" height="${screenUnits(25)}" rx="${screenUnits(4)}" fill="#172b37"/><text data-rotation-degrees x="${x}" y="${y}" style="font-size:${screenUnits(14)}px;text-anchor:start;fill:#ffe4a5;font-weight:600">${label}</text></g>`;}
function overlay(){if(tool!=='rotate'||preview||spaceHeld)return '';const t=target();if(!t)return '';const c=pivotFor(t.o,t.key),ps=points(t.o,t.key),sz=screenUnits(6);return `<path d="M${ps.map(p=>p.join(' ')).join('L')}${t.o.points?'':'Z'}" fill="none" stroke="#ddae65" stroke-width="${screenUnits(1.5)}" pointer-events="none"/>${c?`<circle cx="${c.x}" cy="${c.y}" r="${screenUnits(10)}" fill="none" stroke="#ffe4a5" stroke-width="${screenUnits(2)}" pointer-events="none"/>`:""}`+ps.map((p,i)=>`<circle data-rotate-vertex="${i}" cx="${p[0]}" cy="${p[1]}" r="${sz}" fill="${i===c?.index?'#ddae65':'#223843'}" stroke="#ddae65" stroke-width="${screenUnits(2)}" style="cursor:grab"><title>${c?(i===c.index?'Rotation pivot':'Drag to rotate around the marked corner; click to change pivot'):'Click to set rotation pivot'}</title></circle>`).join('')+(gesture?.moved?feedback(gesture.center,gesture.start,gesture.degrees,gesture.cursor):'');}
function down(e){if(tool!=='rotate'||preview||spaceHeld||window.BuildingExports?.isThreeMode?.()||e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();const h=e.target.closest?.('[data-rotate-vertex]');if(!h){const extra=e.target.closest?.('[data-extra]'),r=room(e.target.closest?.('[data-room]')?.dataset.room)||roomAt(point(e));if(extra)setSelection({[extra.dataset.extra]:[extra.dataset.id]});else if(r){if(!eligible(r,'rooms'))notify('Connected stairs and derived footprints cannot rotate freely');setSelection({rooms:[r.id]});}else setSelection();render();return;}const t=target();if(!t)return;const index=Number(h.dataset.rotateVertex),chosen=pivotFor(t.o,t.key);if(!chosen||chosen.index===index){choosePivot(t.o,t.key,index);draw();notify('Pivot set · drag another corner to rotate · Shift: world 5°');return;}const before=JSON.stringify(model);if(t.key==='annotations'){window.KERN_OBJECTS.normalizeAnnotations(model);t.o=extraObject(t.key,t.o.id);}prepare(t.o,t.key);const p=point(e),c=chosen;gesture={vertex:index,startPointer:p,moved:false,before,key:t.key,id:t.o.id,original:clone(t.o),center:c,start:Math.atan2(p.y-c.y,p.x-c.x),transform:$('plan').getScreenCTM().inverse(),pointerId:e.pointerId};$('plan').setPointerCapture(e.pointerId);}
function move(e){if(!gesture||e.pointerId!==gesture.pointerId)return;e.preventDefault();e.stopImmediatePropagation();const g=gesture,p=point(e,g.transform);if(!g.moved&&Math.hypot(p.x-g.startPointer.x,p.y-g.startPointer.y)<worldPixels(3))return;g.moved=true;const d=delta(g.original,(Math.atan2(p.y-g.center.y,p.x-g.center.x)-g.start)*180/Math.PI,e.shiftKey,g.key),o=g.key==='rooms'?room(g.id):extraObject(g.key,g.id);g.degrees=d;g.cursor=p;apply(o,g.original,d,g.key,g.center);draw();}
function up(e){if(!gesture||e.pointerId!==gesture.pointerId)return;e.preventDefault();e.stopImmediatePropagation();const g=gesture;gesture=null;if($('plan').hasPointerCapture(e.pointerId))$('plan').releasePointerCapture(e.pointerId);if(!g.moved){model=JSON.parse(g.before);const o=g.key==='rooms'?room(g.id):extraObject(g.key,g.id);choosePivot(o,g.key,g.vertex);}else if(JSON.stringify(model)!==g.before){history.push(g.before);if(history.length>80)history.shift();future=[];save();}render();}
$('plan').addEventListener('pointerdown',down,true);$('plan').addEventListener('pointermove',move,true);$('plan').addEventListener('pointerup',up,true);$('plan').addEventListener('pointercancel',cancel,true);$('plan').addEventListener('lostpointercapture',cancel,true);window.addEventListener('blur',cancel);
window.addEventListener('keydown',e=>{if(window.KERN_EXPLORER?.active||isTypingTarget(e.target)||document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='e'&&!e.shiftKey){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat)button.click();}else if(e.key==='Escape'&&tool==='rotate'){e.preventDefault();e.stopImmediatePropagation();cancel();setTool('select');}},true);
const oldTool=setTool;setTool=function(v){cancel();if(v!=='rotate')pivot=null;const result=oldTool(v);sync();return result;};const oldReset=resetTransient;resetTransient=function(...args){cancel();pivot=null;return oldReset(...args);};const oldUndo=undo;undo=function(){if(gesture){cancel();return;}return oldUndo();};$('undo').onclick=()=>undo();
window.KERN_ROTATE={overlay,sync,angle,delta,center,points,prepare,apply,pivotFor,choosePivot,feedback,active:()=>tool==='rotate',eligibleRoom:r=>eligible(r,'rooms')};sync();
})();
